import{assert}from"chrome://resources/js/assert.js";import{sendWithPromise}from"chrome://resources/js/cr.js";import{getImage}from"chrome://resources/js/icon.js";import{createElementFromDictionary,createElementFromText}from"./utils.js";function getSelect(){const select=document.querySelector("#extensions-select");assert(select);return select}function refreshExtensions(){sendWithPromise("getExtensions").then(onGetExtensions)}function onGetExtensions(extensionStatuses){const select=getSelect();const oldSelectedExtension=getSelectedExtensionId();select.textContent="";for(let i=0;i<extensionStatuses.length;i++){const originEntry=extensionStatuses[i];const title=originEntry.extensionName+" ["+originEntry.status+"]";select.options.add(new Option(title,originEntry.extensionID));if(originEntry.extensionID!==oldSelectedExtension){continue}select.options[select.options.length-1].selected=true}refreshFileMetadata()}function getSelectedExtensionId(){const select=getSelect();if(select.selectedIndex>=0){return select.options[select.selectedIndex].value}return null}function refreshFileMetadata(){const dropDown=getSelect();if(dropDown.options.length===0){const header=document.querySelector("#file-metadata-header");assert(header);header.textContent="";const entries=document.querySelector("#file-metadata-entries");assert(entries);entries.textContent="No file metadata available.";return}const selectedExtensionId=getSelectedExtensionId();sendWithPromise("getFileMetadata",selectedExtensionId).then(onGetFileMetadata)}function onGetFileMetadata(fileMetadataMap){const header=document.querySelector("#file-metadata-header");assert(header);if(header.children.length===0){const tr=document.createElement("tr");tr.appendChild(createElementFromText("td","Type"));tr.appendChild(createElementFromText("td","Status"));tr.appendChild(createElementFromText("td","Path",{width:"250px"}));tr.appendChild(createElementFromText("td","Details"));header.appendChild(tr)}const itemContainer=document.querySelector("#file-metadata-entries");assert(itemContainer);itemContainer.textContent="";for(let i=0;i<fileMetadataMap.length;i++){const metadatEntry=fileMetadataMap[i];const tr=document.createElement("tr");tr.appendChild(createFileIconCell(metadatEntry.type));tr.appendChild(createElementFromText("td",metadatEntry.status));tr.appendChild(createElementFromText("td",metadatEntry.path));tr.appendChild(createElementFromDictionary("td",metadatEntry.details));itemContainer.appendChild(tr)}}function createFileIconCell(type){const img=document.createElement("div");const lowerType=type.toLowerCase();if(lowerType==="file"){img.style.content=getImage("chrome://theme/IDR_DEFAULT_FAVICON")}else if(lowerType==="folder"){img.style.content=getImage("chrome://theme/IDR_FOLDER_CLOSED");img.className="folder-image"}const imgWrapper=document.createElement("div");imgWrapper.appendChild(img);const td=document.createElement("td");td.className="file-icon-cell";td.appendChild(imgWrapper);td.appendChild(document.createTextNode(type));return td}function main(){refreshExtensions();const refresh=document.querySelector("#refresh-metadata-button");assert(refresh);refresh.addEventListener("click",refreshExtensions);getSelect().addEventListener("change",refreshFileMetadata)}document.addEventListener("DOMContentLoaded",main);